//! Sprite loading. All art comes from `assets/sprites/`, generated by
//! `tools/gen_sprites.py`; regenerate there, never edit PNGs.

use crate::game::SoundKind;
use crate::numeric;
use aftermine_sim::{BuildingKind, UnitKind};
use anyhow::{Context, Result};
use macroquad::audio::{Sound, load_sound_from_bytes};
use macroquad::prelude::{
    Color, DrawTextureParams, FilterMode, Image, Rect, Texture2D, Vec2, draw_texture_ex,
};

/// Sprite regions share bounded texture pages instead of per-sprite textures.
pub struct Sprites {
    /// Home's title art, kept apart from the atlas: it is the one image drawn
    /// at arbitrary sizes, so it filters smoothly.
    wordmark: Texture2D,
    textures: Vec<Texture2D>,
    entity_lod: crate::entity_lod::EntityLod,
    ground_blend: crate::render::GroundBlend,
    page_height: f32,
    regions: Regions,
}

/// Every atlas region the shell draws, read from the manifest.
struct Regions {
    harvester_body: [[Rect; 2]; 6],
    excavator_body: Vec<[Rect; 2]>,
    scuttler_body: Vec<[Rect; 2]>,
    /// Hull and mount layers for every kind whose look draws a rig.
    unit_rigs: std::collections::HashMap<UnitKind, UnitRig>,
    bombard_spades: [Rect; 5],
    piledriver_anchors: Vec<[Rect; 2]>,
    scout_radar: Rect,
    array_rig: ArrayRig,
    strategic_rigs: StrategicRigs,
    maw_rigs: MawRigs,
    roc_rig: RocRig,
    /// Verb pictograms for cards and order chips, indexed by
    /// [`crate::panel::VerbIcon`].
    verb_icons: [Rect; 16],
    /// Controller button icons, indexed by [`crate::pad::PadIcon`].
    pad_icons: [Rect; 35],
    ground: [Rect; 6],
    ground_detail: [Rect; 12],
    quarry_dressing: [Rect; 12],
    /// Layered rock slabs, indexed `size * ROCK_SLAB_VARIANTS + variant`.
    rock_slabs: [Rect; ROCK_SLAB_SIZES * ROCK_SLAB_VARIANTS],
    /// The derelict 2x2 Extractor frame bed, drawn on unclaimed frames.
    extractor_frame: Rect,
    rock_skirt: Rect,
    wreck_decal: Rect,
    /// Six flat ground-dressing variants for each shipped theme.
    theme_props: [Rect; 18],
    /// Multi-tile industrial obstacles drawn over Rock terrain.
    ground_blockers: [Rect; 9],
    scrap_full: Rect,
    scrap_mid: Rect,
    scrap_low: Rect,
    scrap_rich: Rect,
    scorch: Rect,
    wreck_pile: Rect,
    wreck_piles: [Rect; WRECK_PILES],
    air_shadow: Rect,
    burst: Rect,
    /// Each building kind's art at every rung of its upgrade ladder,
    /// indexed by discriminant then tier.
    buildings: Vec<Vec<RungArt>>,
    /// Chassis art per unit kind, indexed by the kind's discriminant.
    units: Vec<UnitArt>,
    scaffold: Rect,
    debris: [Rect; 3],
    excavator_cargo: [Rect; EXCAVATOR_CARGO_LEVELS],
    mantle_charge: [Rect; MANTLE_CHARGE_FRAMES],
}

impl Regions {
    /// Reads every region from `rects`; a missing one is an error.
    fn read(rects: &Manifest) -> Result<Self> {
        let [
            rock_skirt,
            extractor_frame,
            scrap_full,
            scrap_mid,
            scrap_low,
            scrap_rich,
            scorch,
            wreck_pile,
            air_shadow,
            burst,
        ] = pick(rects, SINGLE_KEYS)?;
        Ok(Self {
            unit_rigs: unit_rigs(rects)?,
            bombard_spades: bombard_spade_rows(rects)?,
            piledriver_anchors: piledriver_anchor_rows(rects)?,
            array_rig: array_rig(rects)?,
            strategic_rigs: strategic_rigs(rects)?,
            maw_rigs: maw_rigs(rects)?,
            roc_rig: roc_rig(rects)?,
            scout_radar: lookup(rects, "scout_radar")?,
            harvester_body: harvester_body_rows(rects)?,
            excavator_body: suffix_rows(
                rects,
                "rig_excavator_body",
                hull_suffixes(UnitKind::Excavator),
            )?,
            scuttler_body: suffix_rows(
                rects,
                "rig_scuttler_body",
                hull_suffixes(UnitKind::Scuttler),
            )?,
            verb_icons: pick(rects, VERB_ICON_KEYS)?,
            pad_icons: pick(rects, PAD_ICON_KEYS)?,
            ground: pick(rects, GROUND_KEYS)?,
            ground_detail: pick(rects, GROUND_DETAIL_KEYS)?,
            quarry_dressing: quarry_dressing_rows(rects)?,
            rock_slabs: pick(rects, ROCK_SLAB_KEYS)?,
            extractor_frame,
            rock_skirt,
            wreck_decal: lookup(rects, "decal_wreck")?,
            theme_props: pick(rects, THEME_PROP_KEYS)?,
            ground_blockers: pick(rects, GROUND_BLOCKER_KEYS)?,
            scrap_full,
            scrap_mid,
            scrap_low,
            scrap_rich,
            scorch,
            wreck_pile,
            wreck_piles: pick(rects, WRECK_PILE_KEYS)?,
            air_shadow,
            burst,
            buildings: building_art(rects)?,
            units: unit_art(rects)?,
            scaffold: lookup(rects, "scaffold_sparse")?,
            debris: pick(rects, DEBRIS_KEYS)?,
            excavator_cargo: excavator_cargo_rows(rects)?,
            mantle_charge: mantle_charge_rows(rects)?,
        })
    }
}

pub(crate) const MANTLE_RECHARGE_STEPS: usize = 16;
const MANTLE_CHARGE_FRAMES: usize = 3 * MANTLE_RECHARGE_STEPS + 1;

/// First slot of every tinted sprite row: the art itself.
const BASE: usize = 0;

/// Second slot of every tinted sprite row: the allegiance-accent mask, the
/// art's tintable regions in grayscale.
const ACCENT: usize = 1;

/// The atlas manifest as `tools/gen_sprites.py` writes it. It remembers every
/// name a loader asks for, so a test can find a shipped region no loader
/// reads.
#[derive(Default)]
pub(crate) struct Manifest {
    rects: std::collections::HashMap<String, [f32; 4]>,
    asked: std::cell::RefCell<std::collections::HashSet<String>>,
}

impl Manifest {
    fn parse(json: &str) -> Result<Self> {
        Ok(Self {
            rects: serde_json::from_str(json)?,
            asked: std::cell::RefCell::default(),
        })
    }

    fn get(&self, name: &str) -> Option<[f32; 4]> {
        self.asked.borrow_mut().insert(name.to_owned());
        self.rects.get(name).copied()
    }

    fn contains_key(&self, name: &str) -> bool {
        self.get(name).is_some()
    }
}

pub(crate) struct ArrayRig {
    base: [[Rect; 2]; 2],
    rotor: [[Rect; 2]; 2],
}

impl ArrayRig {
    pub(crate) fn layers(&self, tier: u8) -> [(Rect, Rect); 2] {
        let tier = usize::from(tier.min(1));
        [self.base[tier], self.rotor[tier]].map(|row| (row[BASE], row[ACCENT]))
    }
}

/// The Spire's runtime layers. The foundation stays put; everything else
/// turns with the deck about the footprint centre.
pub(crate) struct SpireRig {
    pub foundation: [Rect; 2],
    pub deck: [Rect; 2],
    /// One to four seated sections, untinted.
    pub stacks: Vec<Rect>,
    /// The finished warhead on the deck.
    pub round: [Rect; 2],
    /// The painted nose while the gantry carries it.
    pub noses: Vec<[Rect; 2]>,
    pub gantry_parked: Rect,
    /// The hook's carry and return poses.
    pub gantry: Vec<Rect>,
    pub cover: [Rect; 2],
    /// Open, then closing steps to shut.
    pub lock_lower: Vec<Rect>,
    pub lock_upper: Vec<Rect>,
    /// The warhead in flight: coasting, then with its plume flickering.
    pub warhead: Vec<[Rect; 2]>,
}

/// The Lattice's runtime layers: a fixed base, two pods each turning
/// about its own pivot, the shared reload arm, and the cover plate.
pub(crate) struct LatticeRig {
    pub base: Rect,
    pub cover: Rect,
    pub pod: [Rect; 2],
    pub interceptor: [Rect; 2],
    /// One or two seated parts, untinted.
    pub stacks: Vec<Rect>,
    /// Open, then closing steps to shut.
    pub clamp: Vec<Rect>,
    /// The arm's carry and return poses toward the left and right pod.
    pub arms: [Vec<Rect>; 2],
    /// The painted nose while the arm carries it, per side.
    pub noses: [Vec<[Rect; 2]>; 2],
    /// The interceptor's launch: coasting, then with its plume.
    pub launch: Vec<[Rect; 2]>,
}

pub(crate) struct StrategicRigs {
    pub spire: SpireRig,
    pub lattice: LatticeRig,
}

/// How many heat steps each belt scrap clump ships, coldest first.
pub(crate) const MAW_SCRAP_HEAT_STEPS: usize = 4;

/// The Maw's runtime layers. Every layer shares the unit's 256px canvas
/// and turns with the hull about its centre; they draw in field order.
pub(crate) struct MawRig {
    /// Each side's moving cleats, one frame per pixel of their pitch.
    pub treads: [Vec<Rect>; 2],
    /// Everything the moving layers do not redraw.
    pub hull: [Rect; 2],
    /// Conveyor slats, one frame per pixel of their pitch.
    pub slats: Vec<Rect>,
    /// Belt scrap clumps on their own small canvas, variant-major with
    /// [`MAW_SCRAP_HEAT_STEPS`] steps each.
    pub scrap: Vec<Rect>,
    pub kiln: Rect,
    /// The kiln at full heat where heat changes it; drawn at the heat.
    pub glow: Rect,
    /// The drum's arms from stowed to lowered.
    pub arms: Vec<Rect>,
    /// The drum and hood fully lowered, over half a turn of spin.
    pub drum: Vec<[Rect; 2]>,
}

/// The cradle's crane, drawn over its site on the footprint's canvas: the
/// bridge on the middle column and the trolley at the centre, idle then
/// welding. Its crew pads and their lamps, dark then lit, draw on their
/// own tiles.
pub(crate) struct CradleRig {
    pub bridge: [Rect; 2],
    pub trolley: Vec<[Rect; 2]>,
    pub pad: Rect,
    pub lamp: Vec<Rect>,
}

pub(crate) struct MawRigs {
    pub maw: MawRig,
    pub cradle: CradleRig,
}

fn maw_rigs(rects: &Manifest) -> Result<MawRigs> {
    let scrap = plain_numbered(rects, "rig_maw_scrap")?;
    anyhow::ensure!(
        scrap.len() % MAW_SCRAP_HEAT_STEPS == 0,
        "rig_maw_scrap ships {} frames, not whole heat ramps",
        scrap.len()
    );
    Ok(MawRigs {
        maw: MawRig {
            treads: [
                plain_numbered(rects, "rig_maw_tread_left")?,
                plain_numbered(rects, "rig_maw_tread_right")?,
            ],
            hull: variant_row(rects, "rig_maw_hull", "")?,
            slats: plain_numbered(rects, "rig_maw_slats")?,
            scrap,
            kiln: lookup(rects, "rig_maw_kiln")?,
            glow: lookup(rects, "rig_maw_kiln_glow")?,
            arms: plain_numbered(rects, "rig_maw_arms")?,
            drum: numbered_rows(rects, "rig_maw_drum", "")?,
        },
        cradle: CradleRig {
            bridge: variant_row(rects, "rig_cradle_bridge", "")?,
            trolley: tinted_sequence(rects, "rig_cradle_trolley")?,
            pad: lookup(rects, "rig_cradle_pad")?,
            lamp: plain_sequence(rects, "rig_cradle_lamp")?,
        },
    })
}

/// The untinted `{stem}_1`, `{stem}_2`, ... frames the atlas ships.
fn plain_numbered(rects: &Manifest, stem: &str) -> Result<Vec<Rect>> {
    let mut out = Vec::new();
    for frame in 1.. {
        let key = format!("{stem}_{frame}");
        if !rects.contains_key(&key) {
            break;
        }
        out.push(lookup(rects, &key)?);
    }
    anyhow::ensure!(!out.is_empty(), "{stem} ships no frames");
    Ok(out)
}

/// A base key followed by its numbered steps, untinted.
fn plain_sequence(rects: &Manifest, stem: &str) -> Result<Vec<Rect>> {
    let mut out = vec![lookup(rects, stem)?];
    out.extend(plain_numbered(rects, stem)?);
    Ok(out)
}

/// A tinted base row followed by its numbered rows.
fn tinted_sequence(rects: &Manifest, stem: &str) -> Result<Vec<[Rect; 2]>> {
    let mut out = vec![variant_row(rects, stem, "")?];
    out.extend(numbered_rows(rects, stem, "")?);
    Ok(out)
}

fn strategic_rigs(rects: &Manifest) -> Result<StrategicRigs> {
    Ok(StrategicRigs {
        spire: SpireRig {
            foundation: variant_row(rects, "rig_spire_foundation", "")?,
            deck: variant_row(rects, "rig_spire_deck", "")?,
            stacks: plain_numbered(rects, "rig_spire_stack")?,
            round: variant_row(rects, "rig_spire_round", "")?,
            noses: numbered_rows(rects, "rig_spire_nose", "")?,
            gantry_parked: lookup(rects, "rig_spire_gantry")?,
            gantry: plain_numbered(rects, "rig_spire_gantry")?,
            cover: variant_row(rects, "rig_spire_cover", "")?,
            lock_lower: plain_sequence(rects, "rig_spire_lock_lower")?,
            lock_upper: plain_sequence(rects, "rig_spire_lock_upper")?,
            warhead: tinted_sequence(rects, "rig_spire_warhead")?,
        },
        lattice: LatticeRig {
            base: lookup(rects, "rig_lattice_base")?,
            cover: lookup(rects, "rig_lattice_cover")?,
            pod: variant_row(rects, "rig_lattice_pod", "")?,
            interceptor: variant_row(rects, "rig_lattice_interceptor", "")?,
            stacks: plain_numbered(rects, "rig_lattice_stack")?,
            clamp: plain_sequence(rects, "rig_lattice_clamp")?,
            arms: [
                plain_numbered(rects, "rig_lattice_arm_left")?,
                plain_numbered(rects, "rig_lattice_arm_right")?,
            ],
            noses: [
                numbered_rows(rects, "rig_lattice_nose_left", "")?,
                numbered_rows(rects, "rig_lattice_nose_right", "")?,
            ],
            launch: tinted_sequence(rects, "rig_lattice_launch")?,
        },
    })
}

fn array_rig(rects: &Manifest) -> Result<ArrayRig> {
    Ok(ArrayRig {
        base: [
            variant_row(rects, "rig_array_t0_base", "")?,
            variant_row(rects, "rig_array_t1_base", "")?,
        ],
        rotor: [
            variant_row(rects, "rig_array_t0_rotor", "")?,
            variant_row(rects, "rig_array_t1_rotor", "")?,
        ],
    })
}

pub(crate) struct UnitRig {
    hull: Vec<[Rect; 2]>,
    mount: Vec<[Rect; 2]>,
    shadow: Option<Rect>,
    mount_shadow: Option<Rect>,
}

impl UnitRig {
    /// The hull's own ground shadow on the hull's canvas, drawn in place of
    /// the shared airframe shadow.
    pub(crate) fn shadow(&self) -> Option<Rect> {
        self.shadow
    }

    /// Each mounted gun's ground shadow on the gun's canvas.
    pub(crate) fn mount_shadow(&self) -> Option<Rect> {
        self.mount_shadow
    }

    pub(crate) fn hull(&self, phase: usize) -> (Rect, Rect) {
        let row = self.hull[phase.min(self.hull.len() - 1)];
        (row[BASE], row[ACCENT])
    }

    pub(crate) fn mount(&self, action: Option<usize>) -> (Rect, Rect) {
        let row = self.mount[action.map_or(0, |frame| (frame + 1).min(self.mount.len() - 1))];
        (row[BASE], row[ACCENT])
    }
}

fn harvester_body_rows(rects: &Manifest) -> Result<[[Rect; 2]; 6]> {
    variant_rows(
        rects,
        "rig_harvester_body",
        [
            "_cargo0", "_cargo1", "_cargo2", "_cargo3", "_cargo4", "_cargo5",
        ],
    )
}

fn suffix_rows(rects: &Manifest, stem: &str, suffixes: &[&str]) -> Result<Vec<[Rect; 2]>> {
    suffixes
        .iter()
        .map(|suffix| variant_row(rects, stem, suffix))
        .collect()
}

/// A hull's locomotion phases: its rest, then the two move poses for a hull
/// that rocks as it goes. A tracked hull holds still while its belts roll.
fn hull_suffixes(kind: UnitKind) -> &'static [&'static str] {
    if crate::look::unit(kind).belts.is_empty() {
        &["", "_move1", "_move2"]
    } else {
        &[""]
    }
}

/// Every rig the atlas ships for a kind whose look draws one; its mount has
/// a frame per action frame.
fn unit_rigs(rects: &Manifest) -> Result<std::collections::HashMap<UnitKind, UnitRig>> {
    let mut rigs = std::collections::HashMap::new();
    for kind in UnitKind::ALL {
        if crate::look::unit(kind).rig {
            let actions = numbered_suffixes(rects, &rig_mount_stem(kind), "action")?.len();
            rigs.insert(
                kind,
                unit_rig(rects, unit_stem(kind), hull_suffixes(kind), actions)?,
            );
        }
    }
    Ok(rigs)
}

/// The stem of a rigged kind's mount layer, which holds its action frames:
/// the rig draws a hull and a mount in place of whole-body frames.
fn rig_mount_stem(kind: UnitKind) -> String {
    format!("rig_{}_mount", unit_stem(kind))
}

fn unit_rig(rects: &Manifest, stem: &str, hull: &[&str], actions: usize) -> Result<UnitRig> {
    let prefix = format!("rig_{stem}");
    Ok(UnitRig {
        hull: suffix_rows(rects, &format!("{prefix}_hull"), hull)?,
        mount: (0..=actions)
            .map(|action| {
                let suffix = if action == 0 {
                    String::new()
                } else {
                    format!("_action{action}")
                };
                variant_row(rects, &format!("{prefix}_mount"), &suffix)
            })
            .collect::<Result<_>>()?,
        shadow: optional(rects, &format!("{prefix}_shadow"))?,
        mount_shadow: optional(rects, &format!("{prefix}_mount_shadow"))?,
    })
}

fn optional(rects: &Manifest, name: &str) -> Result<Option<Rect>> {
    rects
        .contains_key(name)
        .then(|| lookup(rects, name))
        .transpose()
}

/// The Roc's layers beyond its hull and guns. The wall and yokes share the
/// hull's 256px canvas; each fan and each dock has its own small canvas
/// centred on it, because their edges blend with what lies beneath them.
pub(crate) struct RocRig {
    /// The hull's silhouette dropped toward the tail, drawn first.
    pub wall: Rect,
    /// The guns' fixed yokes, under the guns.
    pub yoke: Rect,
    /// Each fan's blades, one frame per phase of their turn.
    pub fans: [Vec<[Rect; 2]>; 2],
    /// Each dock's clamps from closed to fully open.
    pub docks: Vec<Vec<[Rect; 2]>>,
    /// The hull falling: fans still and docks empty, drawn over the wall,
    /// yokes and guns.
    pub wreck: [Rect; 2],
    /// The cargo hatch from closed to fully open, centred on it.
    pub hatch: Vec<[Rect; 2]>,
    /// The aft thrusters at full heat, drawn at the engines' heat.
    pub glow: Rect,
    /// The whole Roc as its cradle assembles it, guns at rest and docks
    /// empty, faded in by the building opacity steps.
    pub ghost: [Rect; 2],
}

fn roc_rig(rects: &Manifest) -> Result<RocRig> {
    let docks = (1..)
        .map(|dock| format!("rig_roc_dock{dock}"))
        .take_while(|stem| rects.contains_key(&format!("{stem}_1")))
        .map(|stem| numbered_rows(rects, &stem, ""))
        .collect::<Result<Vec<_>>>()?;
    Ok(RocRig {
        wall: lookup(rects, "rig_roc_wall")?,
        yoke: lookup(rects, "rig_roc_yoke")?,
        fans: [
            numbered_rows(rects, "rig_roc_fan_left", "")?,
            numbered_rows(rects, "rig_roc_fan_right", "")?,
        ],
        docks,
        wreck: variant_row(rects, "rig_roc_wreck", "")?,
        hatch: numbered_rows(rects, "rig_roc_hatch", "")?,
        glow: lookup(rects, "rig_roc_glow")?,
        ghost: variant_row(rects, "rig_roc_ghost", "")?,
    })
}

fn piledriver_anchor_rows(rects: &Manifest) -> Result<Vec<[Rect; 2]>> {
    let mut rows = vec![variant_row(rects, "piledriver_anchors", "")?];
    rows.extend(numbered_rows(rects, "piledriver_anchors", "action")?);
    Ok(rows)
}

fn bombard_spade_rows(rects: &Manifest) -> Result<[Rect; 5]> {
    pick(
        rects,
        [
            "bombard_spades_0",
            "bombard_spades_1",
            "bombard_spades_2",
            "bombard_spades_3",
            "bombard_spades_4",
        ],
    )
}

fn quarry_dressing_rows(rects: &Manifest) -> Result<[Rect; 12]> {
    let keys: [String; 12] = std::array::from_fn(|index| format!("quarry_dressing_{index}"));
    pick(rects, keys.each_ref().map(String::as_str))
}

