/// The two whole-body move poses of a kind that draws them.
const MOVE_SUFFIXES: [&str; 2] = ["_move1", "_move2"];
const EXCAVATOR_CARGO_LEVELS: usize = 5;
const SITE_STAGES: usize = aftermine_sim::stats::CONSTRUCTION_STAGES as usize;
const SITE_PHASES: usize = 2;
const SITE_FRAME_COUNT: usize = SITE_STAGES * SITE_PHASES;

/// The atlas stem a unit kind's rows live under.
pub(crate) fn unit_stem(kind: UnitKind) -> &'static str {
    kind.name()
}

/// The atlas stem a building kind's rows live under. Exhaustive on
/// purpose: a new kind must say where its art is before it compiles.
pub(crate) fn building_stem(kind: BuildingKind) -> &'static str {
    match kind {
        BuildingKind::Foundry => "foundry",
        BuildingKind::Turret => "turret",
        BuildingKind::Fabricator => "fabricator",
        BuildingKind::FlakTurret => "flak_turret",
        BuildingKind::Bastion => "bastion",
        BuildingKind::Array => "array",
        BuildingKind::Reclaimer => "reclaimer",
        BuildingKind::RepairBay => "repair_bay",
        BuildingKind::Extractor => "extractor",
        BuildingKind::Airworks => "airworks",
        BuildingKind::Crucible => "crucible",
        BuildingKind::Barricade => "barricade",
        BuildingKind::ScuttleCharge => "scuttle_charge",
        BuildingKind::Spire => "spire",
        BuildingKind::Lattice => "lattice",
        BuildingKind::MawCradle => "maw_cradle",
        BuildingKind::RocCradle => "roc_cradle",
    }
}

/// The two names every tinted row carries: the art and its accent mask.
fn variant_keys(stem: &str, suffix: &str) -> [String; 2] {
    [format!("{stem}{suffix}"), format!("{stem}_accent{suffix}")]
}

fn lookup(rects: &Manifest, name: &str) -> Result<Rect> {
    let [x, y, w, h] = rects
        .get(name)
        .with_context(|| format!("sprite {name:?} missing from atlas"))?;
    Ok(Rect::new(x, y, w, h))
}

fn pick<const N: usize>(rects: &Manifest, keys: [&str; N]) -> Result<[Rect; N]> {
    let mut out = [Rect::new(0.0, 0.0, 0.0, 0.0); N];
    for (slot, key) in out.iter_mut().zip(keys) {
        *slot = lookup(rects, key)?;
    }
    Ok(out)
}

fn variant_row(rects: &Manifest, stem: &str, suffix: &str) -> Result<[Rect; 2]> {
    let mut out = [Rect::new(0.0, 0.0, 0.0, 0.0); 2];
    for (slot, key) in out.iter_mut().zip(variant_keys(stem, suffix)) {
        *slot = lookup(rects, &key)?;
    }
    Ok(out)
}

fn variant_rows<const N: usize>(
    rects: &Manifest,
    stem: &str,
    suffixes: [&str; N],
) -> Result<[[Rect; 2]; N]> {
    let empty = [Rect::new(0.0, 0.0, 0.0, 0.0); 2];
    let mut out = [empty; N];
    for (row, suffix) in out.iter_mut().zip(suffixes) {
        *row = variant_row(rects, stem, suffix)?;
    }
    Ok(out)
}

/// The `_{label}1`, `_{label}2`, ... suffixes of the consecutive complete
/// rows the atlas ships under `stem`: the generated art, not a hand-typed
/// count, says how many frames a family has. A row with only some of its
/// variants is an error.
pub(crate) fn numbered_suffixes(rects: &Manifest, stem: &str, label: &str) -> Result<Vec<String>> {
    let mut suffixes = Vec::new();
    for frame in 1.. {
        let suffix = format!("_{label}{frame}");
        let present = variant_keys(stem, &suffix)
            .iter()
            .filter(|key| rects.contains_key(key.as_str()))
            .count();
        match present {
            0 => break,
            2 => suffixes.push(suffix),
            _ => anyhow::bail!("{stem}{suffix} ships only some of its variants"),
        }
    }
    Ok(suffixes)
}

fn numbered_rows(rects: &Manifest, stem: &str, label: &str) -> Result<Vec<[Rect; 2]>> {
    numbered_suffixes(rects, stem, label)?
        .iter()
        .map(|suffix| variant_row(rects, stem, suffix))
        .collect()
}

fn mantle_charge_rows(rects: &Manifest) -> Result<[Rect; MANTLE_CHARGE_FRAMES]> {
    let mut rows = [Rect::new(0.0, 0.0, 0.0, 0.0); MANTLE_CHARGE_FRAMES];
    for (frame, rect) in rows.iter_mut().enumerate() {
        *rect = lookup(rects, &format!("mantle_charge{frame}"))?;
    }
    Ok(rows)
}

fn excavator_cargo_rows(rects: &Manifest) -> Result<[Rect; EXCAVATOR_CARGO_LEVELS]> {
    let mut out = [Rect::new(0.0, 0.0, 0.0, 0.0); EXCAVATOR_CARGO_LEVELS];
    for (level, rect) in out.iter_mut().enumerate() {
        *rect = lookup(rects, &format!("excavator_cargo{level}"))?;
    }
    Ok(out)
}

/// One unit kind's chassis art: the ready row, its two locomotion poses if
/// it draws them, and however many action frames its atlas bank ships.
struct UnitArt {
    base: [Rect; 2],
    moving: Vec<[Rect; 2]>,
    action: Vec<[Rect; 2]>,
}

/// Loads every kind's art in discriminant order, so accessors can index by
/// `kind as usize`.
fn unit_art(rects: &Manifest) -> Result<Vec<UnitArt>> {
    UnitKind::ALL
        .iter()
        .enumerate()
        .map(|(index, &kind)| {
            anyhow::ensure!(
                kind as usize == index,
                "UnitKind::ALL must list {kind:?} at its discriminant"
            );
            let stem = unit_stem(kind);
            Ok(UnitArt {
                base: variant_row(rects, stem, "")?,
                moving: if draws_body_moves(kind) {
                    suffix_rows(rects, stem, &MOVE_SUFFIXES)?
                } else {
                    Vec::new()
                },
                action: numbered_rows(rects, stem, "action")?,
            })
        })
        .collect()
}

/// Whether a kind draws its whole-body move poses: a rig draws its hull, a
/// worker its body layer, and a tracked hull or the Maw holds still while
/// its treads roll.
fn draws_body_moves(kind: UnitKind) -> bool {
    let look = crate::look::unit(kind);
    !look.rig && look.tool.is_none() && look.belts.is_empty() && kind != UnitKind::Maw
}

/// A building's art at one rung of its upgrade ladder.
struct RungArt {
    hull: [Rect; 2],
    construction: [[Rect; 2]; SITE_FRAME_COUNT],
    /// Activity frames after the hull.
    work: Vec<[Rect; 2]>,
    /// The hull's charge-rack frames, synchronized with its mount.
    charge: Vec<[Rect; 2]>,
    /// A defense's rotating mount and its firing frames.
    mount: Option<([Rect; 2], Vec<[Rect; 2]>)>,
}

impl RungArt {
    fn work_cycle(&self, cycle: f32) -> [Rect; 2] {
        let count = self.work.len();
        if count == 0 {
            return self.hull;
        }
        // A normalized tick can land one float rounding error below its frame.
        let index = numeric::to_usize((cycle.clamp(0.0, 1.0) + f32::EPSILON) * count as f32);
        self.work[index.min(count - 1)]
    }
}

fn construction_stem(kind: BuildingKind, tier: usize) -> String {
    rung_stem(
        building_stem(kind),
        if matches!(kind, BuildingKind::Extractor | BuildingKind::Bastion) {
            tier
        } else {
            0
        },
    )
}

/// The atlas stem of a building's hull or mount at `tier`: every upgraded
/// rung ships its own art.
pub(crate) fn rung_stem(stem: &str, tier: usize) -> String {
    if tier == 0 {
        stem.to_owned()
    } else {
        format!("{stem}_t{tier}")
    }
}

/// Loads every kind's art at every rung of its ladder in discriminant
/// order, like [`unit_art`].
fn building_art(rects: &Manifest) -> Result<Vec<Vec<RungArt>>> {
    BuildingKind::ALL
        .iter()
        .enumerate()
        .map(|(index, &kind)| {
            anyhow::ensure!(
                kind as usize == index,
                "BuildingKind::ALL must list {kind:?} at its discriminant"
            );
            let defense = crate::look::defense(kind);
            (0..kind.tiers().len())
                .map(|tier| {
                    let hull = rung_stem(building_stem(kind), tier);
                    let charge = if defense.is_some_and(|defense| defense.charge_rack) {
                        let charge = numbered_rows(rects, &hull, "action")?;
                        anyhow::ensure!(!charge.is_empty(), "{hull} ships no charge rack");
                        charge
                    } else {
                        Vec::new()
                    };
                    let mount = defense
                        .map(|defense| {
                            let stem = rung_stem(defense.mount, tier);
                            let action = numbered_rows(rects, &stem, "action")?;
                            anyhow::ensure!(!action.is_empty(), "{stem} ships no firing frames");
                            Ok((variant_row(rects, &stem, "")?, action))
                        })
                        .transpose()?;
                    Ok(RungArt {
                        hull: variant_row(rects, &hull, "")?,
                        construction: construction_rows(rects, &construction_stem(kind, tier))?,
                        work: numbered_rows(rects, &hull, "work")?,
                        charge,
                        mount,
                    })
                })
                .collect()
        })
        .collect()
}

fn construction_rows(rects: &Manifest, stem: &str) -> Result<[[Rect; 2]; SITE_FRAME_COUNT]> {
    let empty = [Rect::new(0.0, 0.0, 0.0, 0.0); 2];
    let mut out = [empty; SITE_FRAME_COUNT];
    for stage in 0..SITE_STAGES {
        for phase in 0..SITE_PHASES {
            let frame = stage * SITE_PHASES + phase;
            let suffix = format!("_site{stage}_{phase}");
            out[frame] = variant_row(rects, stem, &suffix)?;
        }
    }
    Ok(out)
}

/// Where game data lives: inside a packaged bundle (see
/// [`crate::paths::bundle_resources`]), or the workspace root for
/// development runs.
pub fn resource_root() -> std::path::PathBuf {
    // Native automation runs from an isolated writable directory so
    // local replays and screenshots cannot perturb a golden walk. It
    // points back at the read-only workspace resources explicitly.
    if let Some(root) = std::env::var_os("AFTERMINE_RESOURCE_ROOT") {
        return root.into();
    }
    crate::paths::bundle_resources().unwrap_or_else(|| std::path::PathBuf::from("."))
}

/// Reads one bundled resource. Resources load as bytes through the
/// filesystem because macroquad's own loaders resolve paths through
/// the app bundle's resource lookup on iOS, which rejects absolute
/// paths.
fn read_resource(path: &std::path::Path) -> Result<Vec<u8>> {
    std::fs::read(path).with_context(|| format!("reading {}", path.display()))
}

/// Reads and decodes a bundled image.
pub(crate) fn load_resource_image(rel: &str) -> Result<Image> {
    let bytes = read_resource(&resource_root().join(rel))?;
    Image::from_file_with_format(&bytes, None).with_context(|| format!("decoding {rel}"))
}

fn atlas_page(mut source: Rect, page_height: f32) -> (usize, Rect) {
    let page = numeric::to_usize(source.y / page_height);
    source.y -= page as f32 * page_height;
    (page, source)
}

impl Sprites {
    /// Loads the atlas up front; a missing or incomplete atlas is a
    /// startup error, not a mid-game pop.
    pub fn load() -> Result<Self> {
        let first = load_resource_image("assets/sprites/atlas.png")
            .context("loading assets/sprites/atlas.png (run from the workspace root)")?;
        let manifest = String::from_utf8(read_resource(
            &resource_root().join("assets/sprites/atlas.json"),
        )?)
        .context("loading assets/sprites/atlas.json")?;
        let rects = Manifest::parse(&manifest).context("parsing atlas manifest")?;
        let page_height = f32::from(first.height);
        let page_count = rects
            .rects
            .values()
            .map(|row| atlas_page(Rect::new(row[0], row[1], row[2], row[3]), page_height).0 + 1)
            .max()
            .unwrap_or(1);
        let mut pages = vec![first];
        for page in 1..page_count {
            let name = format!("assets/sprites/atlas_{page}.png");
            pages.push(load_resource_image(&name).with_context(|| format!("loading {name}"))?);
        }
        let textures = pages
            .iter()
            .map(|page| {
                let texture = Texture2D::from_image(page);
                texture.set_filter(FilterMode::Nearest);
                texture
            })
            .collect();

        let entity_lod = crate::entity_lod::EntityLod::load(&rects.rects, &pages, page_height)?;
        let ground_blend = crate::render::GroundBlend::load()?;
        let wordmark = Texture2D::from_image(
            &load_resource_image("assets/wordmark.png").context("loading assets/wordmark.png")?,
        );
        wordmark.set_filter(FilterMode::Linear);
        Ok(Self {
            wordmark,
            textures,
            entity_lod,
            ground_blend,
            page_height,
            regions: Regions::read(&rects)?,
        })
    }

    /// Home's title art.
    pub(crate) fn wordmark(&self) -> &Texture2D {
        &self.wordmark
    }

    pub(crate) fn harvester_body(&self, cargo: usize) -> (Rect, Rect) {
        let row = self.regions.harvester_body[cargo.min(5)];
        (row[BASE], row[ACCENT])
    }

    pub(crate) fn worker_body(
        &self,
        kind: UnitKind,
        cargo: usize,
        phase: usize,
    ) -> Option<(Rect, Rect)> {
        let rows = match crate::look::unit(kind).tool? {
            crate::look::WorkerTool::Scoop => return Some(self.harvester_body(cargo)),
            crate::look::WorkerTool::Drum => &self.regions.excavator_body,
            crate::look::WorkerTool::Shears => &self.regions.scuttler_body,
        };
        let row = rows[phase.min(rows.len() - 1)];
        Some((row[BASE], row[ACCENT]))
    }

    pub(crate) fn sprite_contact(
        &self,
        source: Rect,
        from: Vec2,
        aim: Vec2,
        origin: Vec2,
        size: Vec2,
    ) -> Option<Vec2> {
        self.entity_lod.contact(source, from, aim, origin, size)
    }

    /// The shaders the terrain cache bakes and composites with.
    pub(crate) fn ground_blend(&self) -> &crate::render::GroundBlend {
        &self.ground_blend
    }

    /// Draw an atlas region from its page while preserving its authored canvas.
    pub fn draw(&self, x: f32, y: f32, tint: Color, mut params: DrawTextureParams) {
        if tint.a <= 0.0 {
            return;
        }
        if self
            .entity_lod
            .draw(macroquad::prelude::vec2(x, y), tint, &params)
        {
            return;
        }
        let page = if let Some(source) = params.source {
            let (page, local) = atlas_page(source, self.page_height);
            params.source = Some(local);
            page
        } else {
            0
        };
        draw_texture_ex(&self.textures[page], x, y, tint, params);
    }

    pub fn draw_unit(&self, x: f32, y: f32, tint: Color, params: DrawTextureParams, zoom: f32) {
        let tint = Color {
            a: tint.a * (1.0 - crate::strategic_markers::marker_alpha(zoom)),
            ..tint
        };
        self.draw(x, y, tint, params);
    }

    pub fn draw_building(&self, x: f32, y: f32, tint: Color, params: DrawTextureParams, zoom: f32) {
        let fade = 1.0 - 0.45 * crate::strategic_markers::marker_alpha(zoom);
        self.draw(
            x,
            y,
            Color {
                r: tint.r * fade,
                g: tint.g * fade,
                b: tint.b * fade,
                ..tint
            },
            params,
        );
    }

    pub fn draw_portrait(&self, dest: Rect, layers: &[(Rect, Color)]) {
        use macroquad::prelude::*;
        let bounds = layers
            .iter()
            .map(|(source, _)| self.entity_lod.bounds(*source))
            .reduce(macroquad::math::Rect::combine_with)
            .unwrap_or(Rect::new(0.0, 0.0, 1.0, 1.0));
        let inset = dest.w.min(dest.h) * 0.05;
        let extent =
            (dest.w - 2.0 * inset).min(dest.h - 2.0 * inset) / bounds.w.max(bounds.h).max(0.01);
        let dpi = screen_dpi_scale();
        let x =
            ((dest.x + dest.w * 0.5 - (bounds.x + bounds.w * 0.5) * extent) * dpi).round() / dpi;
        let y =
            ((dest.y + dest.h * 0.5 - (bounds.y + bounds.h * 0.5) * extent) * dpi).round() / dpi;
        let extent = (extent * dpi).round() / dpi;
        self.draw_canvas(Rect::new(x, y, extent, extent), layers);
    }

    /// Compose layers in a shared authored canvas without portrait cropping.
    pub fn draw_canvas(&self, dest: Rect, layers: &[(Rect, Color)]) {
        for &(source, tint) in layers {
            self.draw(
                dest.x,
                dest.y,
                tint,
                DrawTextureParams {
                    source: Some(source),
                    dest_size: Some(macroquad::prelude::vec2(dest.w, dest.h)),
                    ..Default::default()
                },
            );
        }
    }

    /// A verb pictogram's atlas region.
    pub fn verb_icon(&self, icon: crate::panel::VerbIcon) -> Rect {
        self.regions.verb_icons[icon as usize]
    }

    /// A controller button icon's atlas region.
    pub(crate) fn pad_icon(&self, icon: crate::pad::PadIcon) -> Rect {
        self.regions.pad_icons[icon as usize]
    }

    /// A ground variant's atlas region.
    pub fn ground(&self, variant: usize) -> Rect {
        self.regions.ground[variant % self.regions.ground.len()]
    }

    /// A ground grit-and-crack overlay's atlas region.
    pub fn ground_detail(&self, variant: usize) -> Rect {
        self.regions.ground_detail[variant % self.regions.ground_detail.len()]
    }

    pub fn ground_detail_count(&self) -> usize {
        self.regions.ground_detail.len()
    }

    pub(crate) fn quarry_dressing(&self, variant: usize) -> Rect {
        self.regions.quarry_dressing[variant % self.regions.quarry_dressing.len()]
    }

    /// A layered rock slab's atlas region; its pixel size is the slab's
    /// canvas at 64 pixels per tile, centered on the slab.
    pub(crate) fn rock_slab(&self, size: usize, variant: usize) -> Rect {
        self.regions.rock_slabs
            [size.min(ROCK_SLAB_SIZES - 1) * ROCK_SLAB_VARIANTS + variant % ROCK_SLAB_VARIANTS]
    }

    /// A raised industrial obstacle's atlas region.
    pub fn ground_blocker(&self, variant: usize) -> Rect {
        self.regions.ground_blockers[variant % self.regions.ground_blockers.len()]
    }

    /// A building's art at its upgrade-ladder rung.
    fn rung(&self, kind: BuildingKind, tier: u8) -> &RungArt {
        let rungs = &self.regions.buildings[kind as usize];
        &rungs[usize::from(tier).min(rungs.len() - 1)]
    }

    /// A defense's tier-appropriate directional mount, if its base art ships bare.
    pub fn defense_mount(&self, kind: BuildingKind, tier: u8) -> Option<Rect> {
        let (row, _) = self.rung(kind, tier).mount.as_ref()?;
        Some(row[BASE])
    }

    /// The allegiance-accent mask matched to [`Self::defense_mount`].
    pub fn defense_mount_accent(&self, kind: BuildingKind, tier: u8) -> Option<Rect> {
        let (row, _) = self.rung(kind, tier).mount.as_ref()?;
        Some(row[ACCENT])
    }

    fn defense_mount_action_row(
        &self,
        kind: BuildingKind,
        tier: u8,
        frame: usize,
    ) -> Option<&[Rect; 2]> {
        let (_, action) = self.rung(kind, tier).mount.as_ref()?;
        action.get(frame)
    }

    /// A defense mount's zero-based authored action frame. An out-of-range
    /// frame falls back to the ready mount; unarmed buildings return `None`.
    pub fn defense_mount_action(&self, kind: BuildingKind, tier: u8, frame: usize) -> Option<Rect> {
        self.defense_mount_action_row(kind, tier, frame)
            .map(|row| row[BASE])
            .or_else(|| self.defense_mount(kind, tier))
    }

    /// The allegiance mask matched to [`Self::defense_mount_action`].
    pub fn defense_mount_action_accent(
        &self,
        kind: BuildingKind,
        tier: u8,
        frame: usize,
    ) -> Option<Rect> {
        self.defense_mount_action_row(kind, tier, frame)
            .map(|row| row[ACCENT])
            .or_else(|| self.defense_mount_accent(kind, tier))
    }

    /// The derelict Extractor frame bed (2x2 tiles).
    pub fn extractor_frame(&self) -> Rect {
        self.regions.extractor_frame
    }

    /// The soft shadow a rock casts on a neighboring ground tile
    /// (authored falling from the top edge; rotate toward the rock).
    pub fn rock_skirt(&self) -> Rect {
        self.regions.rock_skirt
    }

    /// The wreck decal's atlas region.
    pub fn wreck_decal(&self) -> Rect {
        self.regions.wreck_decal
    }

    /// A flat ground-dressing mark for a shipped map theme; only the first
    /// three of a theme's marks ship.
    pub fn theme_prop(&self, theme: &str, variant: usize) -> Option<Rect> {
        let row = theme_prop_row(theme)?;
        (variant < 3).then(|| self.regions.theme_props[row * 3 + variant])
    }

    /// The scrap sprite region for a remaining amount: anything above a
    /// standard node renders as the rich pile, then thirds of standard.
    pub fn scrap(&self, amount: u32, standard_amount: u32) -> Rect {
        if amount > standard_amount {
            self.regions.scrap_rich
        } else if amount * 3 > standard_amount * 2 {
            self.regions.scrap_full
        } else if amount * 3 > standard_amount {
            self.regions.scrap_mid
        } else {
            self.regions.scrap_low
        }
    }

    /// The building-death scorch decal region.
    pub fn scorch(&self) -> Rect {
        self.regions.scorch
    }

    /// A wreck salvage pile on open ground.
    pub fn wreck_pile(&self) -> Rect {
        self.regions.wreck_pile
    }

    /// The pile a wreck shows for the salvage it holds, so it steps down as
    /// it is stripped or decays. `shape` picks among a size's versions.
    pub fn wreck_pile_holding(&self, salvage: u32, shape: usize) -> Rect {
        self.regions.wreck_piles[wreck_pile_size(salvage) * 2 + shape % 2]
    }

    /// The soft shadow a flyer casts on the ground.
    pub fn air_shadow(&self) -> Rect {
        self.regions.air_shadow
    }

    /// The splash-detonation frame.
    pub fn burst(&self) -> Rect {
        self.regions.burst
    }

    /// The building sprite region for a kind.
    fn building_row(&self, kind: aftermine_sim::BuildingKind) -> &[Rect; 2] {
        &self.rung(kind, 0).hull
    }

    pub fn building(&self, kind: aftermine_sim::BuildingKind) -> Rect {
        self.building_row(kind)[BASE]
    }

    /// The hull for a building at its upgrade-ladder rung.
    pub fn building_tiered(&self, kind: aftermine_sim::BuildingKind, tier: u8) -> Rect {
        self.rung(kind, tier).hull[BASE]
    }

    /// The allegiance mask matched to [`Self::building_tiered`].
    pub fn building_tiered_accent(&self, kind: aftermine_sim::BuildingKind, tier: u8) -> Rect {
        self.rung(kind, tier).hull[ACCENT]
    }

    fn building_action_row(&self, kind: BuildingKind, tier: u8, frame: usize) -> &[Rect; 2] {
        let rung = self.rung(kind, tier);
        rung.charge.get(frame).unwrap_or(&rung.hull)
    }

    /// A building base's zero-based authored action frame at `tier`. Bastion
    /// charge cells live here; other building bases and invalid frames stay
    /// ready.
    pub fn building_action(&self, kind: BuildingKind, tier: u8, frame: usize) -> Rect {
        self.building_action_row(kind, tier, frame)[BASE]
    }

    /// The allegiance mask matched to [`Self::building_action`].
    pub fn building_action_accent(&self, kind: BuildingKind, tier: u8, frame: usize) -> Rect {
        self.building_action_row(kind, tier, frame)[ACCENT]
    }

    fn building_work_row(&self, kind: BuildingKind, tier: u8, frame: usize) -> &[Rect; 2] {
        let rung = self.rung(kind, tier);
        frame
            .checked_sub(1)
            .and_then(|index| rung.work.get(index))
            .unwrap_or(&rung.hull)
    }

    /// A complete authored activity frame for a working building. Frame 0
    /// is the ordinary base art and is also the reduced-motion pose.
    pub fn building_working(&self, kind: BuildingKind, tier: u8, frame: usize) -> Rect {
        self.building_work_row(kind, tier, frame)[BASE]
    }

    /// The allegiance mask matched to [`Self::building_working`].
    pub fn building_working_accent(&self, kind: BuildingKind, tier: u8, frame: usize) -> Rect {
        self.building_work_row(kind, tier, frame)[ACCENT]
    }

    /// Samples every installed work pose, with matching hull and owner mask.
    pub fn building_work_cycle(&self, kind: BuildingKind, tier: u8, cycle: f32) -> (Rect, Rect) {
        let row = self.rung(kind, tier).work_cycle(cycle);
        (row[BASE], row[ACCENT])
    }

    fn construction_row(
        &self,
        kind: BuildingKind,
        tier: u8,
        stage: usize,
        phase: usize,
    ) -> &[Rect; 2] {
        let stage = stage.min(SITE_STAGES - 1);
        let phase = phase.min(SITE_PHASES - 1);
        &self.rung(kind, tier).construction[stage * SITE_PHASES + phase]
    }

    /// A full construction-site frame authored for the final building's
    /// footprint, progress stage, and machinery phase.
    pub fn construction(&self, kind: BuildingKind, tier: u8, stage: usize, phase: usize) -> Rect {
        self.construction_row(kind, tier, stage, phase)[BASE]
    }

    /// The allegiance mask matched to [`Self::construction`].
    pub fn construction_accent(
        &self,
        kind: BuildingKind,
        tier: u8,
        stage: usize,
        phase: usize,
    ) -> Rect {
        self.construction_row(kind, tier, stage, phase)[ACCENT]
    }

    /// Centered charge bars and the next serial recharge.
    pub(crate) fn mantle_charge(&self, frame: usize) -> Rect {
        self.regions.mantle_charge[frame.min(MANTLE_CHARGE_FRAMES - 1)]
    }
    /// The recessed Excavator meter at one of five load-fraction levels.
    pub fn excavator_cargo(&self, cargo: usize) -> Rect {
        self.regions.excavator_cargo[cargo.min(EXCAVATOR_CARGO_LEVELS - 1)]
    }

    fn moving_unit_row(&self, kind: UnitKind, frame: usize) -> &[Rect; 2] {
        let art = &self.regions.units[kind as usize];
        frame
            .checked_sub(1)
            .and_then(|index| art.moving.get(index))
            .unwrap_or(&art.base)
    }

    /// A unit's authored locomotion phase. Frame 0 is the ordinary base art;
    /// frames 1 and 2 select the two movement poses.
    pub fn unit_moving(&self, kind: UnitKind, frame: usize) -> Rect {
        self.moving_unit_row(kind, frame)[BASE]
    }

    /// The allegiance mask matched to [`Self::unit_moving`].
    pub fn unit_moving_accent(&self, kind: UnitKind, frame: usize) -> Rect {
        self.moving_unit_row(kind, frame)[ACCENT]
    }

    /// The construction lattice.
    pub fn scaffold(&self) -> Rect {
        self.regions.scaffold
    }

    /// A death-scatter hull shard.
    pub fn debris(&self, variant: usize) -> Rect {
        self.regions.debris[variant % 3]
    }

    fn unit_row(&self, kind: UnitKind) -> &[Rect; 2] {
        &self.regions.units[kind as usize].base
    }

    fn unit_action_row(&self, kind: UnitKind, frame: usize) -> Option<&[Rect; 2]> {
        self.regions.units[kind as usize].action.get(frame)
    }

    /// A unit's zero-based authored action frame. Harvester and invalid frame
    /// requests fall back to the ordinary ready sprite.
    pub fn unit_action(&self, kind: UnitKind, frame: usize) -> Rect {
        self.unit_action_row(kind, frame)
            .unwrap_or_else(|| self.unit_row(kind))[BASE]
    }

    /// The allegiance mask matched to [`Self::unit_action`].
    pub fn unit_action_accent(&self, kind: UnitKind, frame: usize) -> Rect {
        self.unit_action_row(kind, frame)
            .unwrap_or_else(|| self.unit_row(kind))[ACCENT]
    }

    /// The unit sprite region for a kind.
    pub fn unit(&self, kind: UnitKind) -> Rect {
        self.unit_row(kind)[BASE]
    }

    pub(crate) fn unit_rig(&self, kind: UnitKind) -> Option<&UnitRig> {
        self.regions.unit_rigs.get(&kind)
    }

    pub(crate) fn scout_radar(&self) -> Rect {
        self.regions.scout_radar
    }

    pub(crate) fn array_rig(&self) -> &ArrayRig {
        &self.regions.array_rig
    }

    pub(crate) fn strategic_rigs(&self) -> &StrategicRigs {
        &self.regions.strategic_rigs
    }

    pub(crate) fn maw_rigs(&self) -> &MawRigs {
        &self.regions.maw_rigs
    }

    pub(crate) fn roc_rig(&self) -> &RocRig {
        &self.regions.roc_rig
    }

    /// A magazine's finished round, body then accent: the warhead seated on
    /// a Spire's deck or a Lattice's interceptor.
    pub(crate) fn round(&self, kind: aftermine_sim::BuildingKind) -> Option<[Rect; 2]> {
        let rigs = &self.regions.strategic_rigs;
        match kind {
            aftermine_sim::BuildingKind::Spire => Some(rigs.spire.round),
            aftermine_sim::BuildingKind::Lattice => Some(rigs.lattice.interceptor),
            _ => None,
        }
    }

    pub(crate) fn piledriver_anchors(&self, deployment: f32) -> (Rect, Rect) {
        let rows = &self.regions.piledriver_anchors;
        let index =
            numeric::to_usize((deployment.clamp(0.0, 1.0) * (rows.len() - 1) as f32).round());
        let row = rows[index];
        (row[BASE], row[ACCENT])
    }

    /// The spade row for a Bombard's deployment, from stowed (row 0) to
    /// fully braced (row 4).
    pub(crate) fn bombard_spades(&self, brace_ticks: u8) -> Rect {
        let deploy = UnitKind::Bombard
            .stats()
            .brace
            .map_or(1, |brace| u16::from(brace.deploy_ticks.max(1)));
        let row = (u16::from(brace_ticks) * 4).div_ceil(deploy).min(4);
        self.regions.bombard_spades[usize::from(row)]
    }

    /// The allegiance-accent mask over a unit's tintable regions: grayscale in the atlas, tinted at draw time.
    pub fn unit_accent(&self, kind: UnitKind) -> Rect {
        self.unit_row(kind)[ACCENT]
    }
}

/// Every clip the shell plays. Generated by `tools/gen_sounds.py`.
pub struct Sounds {
    /// One clip per sound kind, named by [`crate::mixer::spec`]. Each loop
    /// plays from its own voices below instead.
    effects: std::collections::HashMap<SoundKind, Sound>,
    /// The zap's lower sibling, alternated per shot.
    pub laser2: Sound,
    /// Loaded once per voice, because the backend stops by sound id; voices
    /// loaded from one clip share its decoded samples.
    pub rocket_motors: Vec<Sound>,
    /// The same, one per warhead motor voice.
    pub warhead_motors: Vec<Sound>,
    /// The same, one per interceptor motor voice.
    pub interceptor_motors: Vec<Sound>,
    /// The same, one per Maw drum voice.
    pub maw_cuts: Vec<Sound>,
    /// The same, one per Maw kiln voice.
    pub maw_kilns: Vec<Sound>,
    /// Front-end industrial ambience.
    pub music_menu: Sound,
    /// The calm match bed.
    pub music_calm: Sound,
    /// Rhythmic pressure layered over the calm bed during combat.
    pub music_combat: Sound,
    /// A neutral result bed for draws.
    pub music_result: Sound,
    /// The local-player victory bed.
    pub music_victory: Sound,
    /// The local-player defeat or surrender bed.
    pub music_defeat: Sound,
}

async fn clip(name: &str) -> Result<Sound> {
    let candidate = std::env::var("AFTERMINE_SOUND_BANK")
        .ok()
        .map(|root| std::path::PathBuf::from(root).join(format!("{name}.wav")))
        .filter(|path| path.is_file());
    let path =
        candidate.unwrap_or_else(|| resource_root().join(format!("assets/sounds/{name}.wav")));
    let bytes = read_resource(&path).context("loading a sound (run from the workspace root)")?;
    load_sound_from_bytes(&bytes)
        .await
        .with_context(|| format!("decoding {}", path.display()))
}

impl Sounds {
    /// Loads every clip up front, like [`Sprites::load`].
    pub async fn load() -> Result<Self> {
        let mut rocket_motors = Vec::with_capacity(crate::rocket_audio::MOTOR_VOICES);
        for _ in 0..crate::rocket_audio::MOTOR_VOICES {
            rocket_motors.push(clip("avalanche_motor").await?);
        }
        let mut warhead_motors = Vec::with_capacity(crate::strike_audio::WARHEAD_VOICES);
        for _ in 0..crate::strike_audio::WARHEAD_VOICES {
            warhead_motors.push(clip("warhead_flight").await?);
        }
        let mut interceptor_motors = Vec::with_capacity(crate::strike_audio::INTERCEPTOR_VOICES);
        for _ in 0..crate::strike_audio::INTERCEPTOR_VOICES {
            interceptor_motors.push(clip("interceptor_flight").await?);
        }
        let mut maw_cuts = Vec::with_capacity(crate::maw_audio::MAW_VOICES);
        let mut maw_kilns = Vec::with_capacity(crate::maw_audio::MAW_VOICES);
        for _ in 0..crate::maw_audio::MAW_VOICES {
            maw_cuts.push(clip("maw_cut").await?);
            maw_kilns.push(clip("maw_kiln").await?);
        }
        let mut effects = std::collections::HashMap::new();
        for kind in SoundKind::ALL {
            if !matches!(
                kind,
                SoundKind::RocketMotor
                    | SoundKind::WarheadMotor
                    | SoundKind::InterceptorMotor
                    | SoundKind::MawCut
                    | SoundKind::MawKiln
            ) {
                effects.insert(kind, clip(crate::mixer::spec(kind).clip).await?);
            }
        }
        Ok(Self {
            effects,
            laser2: clip("laser2").await?,
            rocket_motors,
            warhead_motors,
            interceptor_motors,
            maw_cuts,
            maw_kilns,
            music_menu: clip("music_menu").await?,
            music_calm: clip("music_calm").await?,
            music_combat: clip("music_combat").await?,
            music_result: clip("music_result").await?,
            music_victory: clip("music_victory").await?,
            music_defeat: clip("music_defeat").await?,
        })
    }

    /// The clip a sound kind plays.
    pub fn effect(&self, kind: SoundKind) -> &Sound {
        match kind {
            SoundKind::RocketMotor => &self.rocket_motors[0],
            SoundKind::WarheadMotor => &self.warhead_motors[0],
            SoundKind::InterceptorMotor => &self.interceptor_motors[0],
            SoundKind::MawCut => &self.maw_cuts[0],
            SoundKind::MawKiln => &self.maw_kilns[0],
            _ => &self.effects[&kind],
        }
    }
}

